// Pets & breeds concept glossary (Hebrew). A page per well-known dog breed (incl. the Canaan dog), cat breed,
// small pet, pet bird, aquarium fish, pet reptile and horse type, plus the key terms (breed, microchip, rabies,
// neutering, shelter…). The basic animal pages already on /animals/* (dog, cat, horse, rabbit, golden hamster,
// budgerigar, goldfish) are linked from the lessons and not repeated here. Sizes and life spans are typical
// ranges, written cautiously ("בדרך כלל", "כ־"). No breed is called dangerous or "the best"; every animal is an
// individual. Israeli rules (rabies vaccine, microchip, licence, protected wildlife) checked 2026-10-30 against
// municipal/gov sources and news; readers are told to confirm with a vet or the local authority.
const q = (question, right, wrong, exp) => ({ q: question, options: [right, ...wrong], exp })
// kind 'term' → "מה זה …?"; kind 'breed' (default) → "… — עובדות לילדים".
const concept = ({ kind = 'breed', ...c }) => ({
  title: kind === 'term' ? `מה זה ${c.term}?` : `${c.term}: עובדות לילדים`,
  seoTitle: kind === 'term' ? `מה זה ${c.term}? הסבר פשוט לילדים, דוגמאות וחידון` : `${c.term} — עובדות לילדים, אופי, טיפול וחידון`,
  // The short definition plus a note, trimmed to what fits a search snippet (≤ 168 characters).
  seoDesc: c.seoDesc || [`${c.short} הסבר לילדים עם דוגמאות וחידון.`, `${c.short} עם חידון.`, c.short].find(s => s.length <= 168),
  ...c
})

